journal.mjs.source:
// The execution journal of a REPL session in the JS host, byte for byte as
// `hd_run` writes and reads it (crates/hd_run/src/journal.rs and
// replay.rs; docs/future-work/live-execution.md §4 and §5), so a journal the wasmtime
// session recorded replays here and one recorded here replays there.
//
// `journal = Header Row*`; `Row = kind: u8, index: uleb, len: uleb,
// payload, crc32: u32 LE`. The payload of each kind, the method naming of
// `Call` rows, the request (scalar parameters as uleb of their two's
// complement bits or 8 float bytes, then the exchange buffer bytes the call
// read, kept when 8 bytes or fewer and else as their digest) and the reply
// (a tag byte, the value, result bytes) are journal.rs's.
//
// Hashes are xxh3-128 with the default secret, as `hd_base::hash128`: an
// `Input` row holds the hash of the input's source text and of its module,
// and a request digest is the low half of the hash of the `StableHasher`
// tag `req` (its length as a u32, then its bytes) followed by the request.
//
// Values: integers that may pass 2^53 are bigints. A reply value is
// `{ tag: 0 }` (void), `{ tag: 1, v }` (an i64), `{ tag: 2, v }` (the bits
// of an f64) or `{ tag: 3, v, w }` (a status and a value, i32s). An end is
// `{ kind: "exit", status }`, or `{ kind }` with `trapped`, `stopped`,
// `cancelled` or `failed`.

const M64 = (1n << 64n) - 1n;
const utf8 = new TextEncoder();

// --- xxh3-128 (the scalar reference, seed 0) -----------------------------

const P32_1 = 0x9e3779b1n;
const P32_2 = 0x85ebca77n;
const P32_3 = 0xc2b2ae3dn;
const P64_1 = 0x9e3779b185ebca87n;
const P64_2 = 0xc2b2ae3d27d4eb4fn;
const P64_3 = 0x165667b19e3779f9n;
const P64_4 = 0x85ebca77c2b2ae63n;
const P64_5 = 0x27d4eb2f165667c5n;

// prettier-ignore
const SECRET = Uint8Array.of(
  0xb8, 0xfe, 0x6c, 0x39, 0x23, 0xa4, 0x4b, 0xbe, 0x7c, 0x01, 0x81, 0x2c, 0xf7, 0x21, 0xad, 0x1c,
  0xde, 0xd4, 0x6d, 0xe9, 0x83, 0x90, 0x97, 0xdb, 0x72, 0x40, 0xa4, 0xa4, 0xb7, 0xb3, 0x67, 0x1f,
  0xcb, 0x79, 0xe6, 0x4e, 0xcc, 0xc0, 0xe5, 0x78, 0x82, 0x5a, 0xd0, 0x7d, 0xcc, 0xff, 0x72, 0x21,
  0xb8, 0x08, 0x46, 0x74, 0xf7, 0x43, 0x24, 0x8e, 0xe0, 0x35, 0x90, 0xe6, 0x81, 0x3a, 0x26, 0x4c,
  0x3c, 0x28, 0x52, 0xbb, 0x91, 0xc3, 0x00, 0xcb, 0x88, 0xd0, 0x65, 0x8b, 0x1b, 0x53, 0x2e, 0xa3,
  0x71, 0x64, 0x48, 0x97, 0xa2, 0x0d, 0xf9, 0x4e, 0x38, 0x19, 0xef, 0x46, 0xa9, 0xde, 0xac, 0xd8,
  0xa8, 0xfa, 0x76, 0x3f, 0xe3, 0x9c, 0x34, 0x3f, 0xf9, 0xdc, 0xbb, 0xc7, 0xc7, 0x0b, 0x4f, 0x1d,
  0x8a, 0x51, 0xe0, 0x4b, 0xcd, 0xb4, 0x59, 0x31, 0xc8, 0x9f, 0x7e, 0xc9, 0xd9, 0x78, 0x73, 0x64,
  0xea, 0xc5, 0xac, 0x83, 0x34, 0xd3, 0xeb, 0xc3, 0xc5, 0x81, 0xa0, 0xff, 0xfa, 0x13, 0x63, 0xeb,
  0x17, 0x0d, 0xdd, 0x51, 0xb7, 0xf0, 0xda, 0x49, 0xd3, 0x16, 0x55, 0x26, 0x29, 0xd4, 0x68, 0x9e,
  0x2b, 0x16, 0xbe, 0x58, 0x7d, 0x47, 0xa1, 0xfc, 0x8f, 0xf8, 0xb8, 0xd1, 0x7a, 0xd0, 0x31, 0xce,
  0x45, 0xcb, 0x3a, 0x8f, 0x95, 0x16, 0x04, 0x28, 0xaf, 0xd7, 0xfb, 0xca, 0xbb, 0x4b, 0x40, 0x7e,
);
const SV = new DataView(SECRET.buffer);

const add = (a, b) => (a + b) & M64;
const mul = (a, b) => (a * b) & M64;
const neg = (a) => -a & M64;
const xorshift = (v, s) => v ^ (v >> s);
const mul128 = (a, b) => {
  const p = a * b;
  return [p & M64, p >> 64n];
};
const fold = (a, b) => {
  const p = a * b;
  return (p & M64) ^ (p >> 64n);
};
const bswap64 = (v) => {
  let r = 0n;
  for (let i = 0; i < 8; i++) r = (r << 8n) | ((v >> BigInt(8 * i)) & 0xffn);
  return r;
};
const bswap32 = (v) => ((v & 0xff) << 24) | ((v & 0xff00) << 8) | ((v >>> 8) & 0xff00) | (v >>> 24);
const avalanche = (v) => xorshift(mul(xorshift(v, 37n), 0x165667919e3779f9n), 32n);
const avalanche64 = (v) => {
  v = mul(xorshift(v, 33n), P64_2);
  v = mul(xorshift(v, 29n), P64_3);
  return xorshift(v, 32n);
};
const s64 = (at) => SV.getBigUint64(at, true);
const s32 = (at) => BigInt(SV.getUint32(at, true));
const join128 = (lo, hi) => lo | (hi << 64n);

function short128(b, dv) {
  const len = b.length;
  const r64 = (at) => dv.getBigUint64(at, true);
  if (len > 8) {
    const lo = r64(0);
    let hi = r64(len - 8);
    let [ml, mh] = mul128(lo ^ hi ^ (s64(32) ^ s64(40)), P64_1);
    ml = add(ml, BigInt(len - 1) << 54n);
    hi ^= s64(48) ^ s64(56);
    mh = add(mh, add(hi, (hi & 0xffffffffn) * (P32_2 - 1n)));
    ml ^= bswap64(mh);
    const [rl, rh] = mul128(ml, P64_2);
    return join128(avalanche(rl), avalanche(add(rh, mul(mh, P64_2))));
  }
  if (len >= 4) {
    const input = BigInt(dv.getUint32(0, true)) + (BigInt(dv.getUint32(len - 4, true)) << 32n);
    let [lo, hi] = mul128(input ^ (s64(16) ^ s64(24)), add(P64_1, BigInt(len) << 2n));
    hi = add(hi, (lo << 1n) & M64);
    lo ^= hi >> 3n;
    lo = xorshift(mul(xorshift(lo, 35n), 0x9fb21c651e98df25n), 28n);
    return join128(lo, avalanche(hi));
  }
  if (len > 0) {
    const lo32 = ((b[0] << 16) | (b[len >> 1] << 24) | b[len - 1] | (len << 8)) >>> 0;
    const swapped = bswap32(lo32) >>> 0;
    const hi32 = ((swapped << 13) | (swapped >>> 19)) >>> 0;
    const lo = avalanche64(BigInt(lo32) ^ (s32(0) ^ s32(4)));
    const hi = avalanche64(BigInt(hi32) ^ (s32(8) ^ s32(12)));
    return join128(lo, hi);
  }
  return join128(avalanche64(s64(64) ^ s64(72)), avalanche64(s64(80) ^ s64(88)));
}

function mid128(b, dv) {
  const len = b.length;
  const r64 = (at) => dv.getBigUint64(at, true);
  const mix16 = (at, sat) => fold(r64(at) ^ s64(sat), r64(at + 8) ^ s64(sat + 8));
  let a0 = mul(BigInt(len), P64_1);
  let a1 = 0n;
  const mix32 = (at1, at2, sat) => {
    a0 = add(a0, mix16(at1, sat)) ^ add(r64(at2), r64(at2 + 8));
    a1 = add(a1, mix16(at2, sat + 16)) ^ add(r64(at1), r64(at1 + 8));
  };
  if (len <= 128) {
    if (len > 32) {
      if (len > 64) {
        if (len > 96) mix32(48, len - 64, 96);
        mix32(32, len - 48, 64);
      }
      mix32(16, len - 32, 32);
    }
    mix32(0, len - 16, 0);
  } else {
    for (let i = 0; i < 4; i++) mix32(32 * i, 32 * i + 16, 32 * i);
    a0 = avalanche(a0);
    a1 = avalanche(a1);
    const rounds = Math.floor(len / 32);
    for (let i = 4; i < rounds; i++) mix32(32 * i, 32 * i + 16, 3 + 32 * (i - 4));
    mix32(len - 16, len - 32, 136 - 17 - 16);
  }
  const lo = add(a0, a1);
  const hi = add(add(mul(a0, P64_1), mul(a1, P64_4)), mul(BigInt(len), P64_2));
  return join128(avalanche(lo), neg(avalanche(hi)));
}

function long128(b, dv) {
  const len = b.length;
  const acc = [P32_3, P64_1, P64_2, P64_3, P64_4, P32_2, P64_5, P32_1];
  const stripe = (at, sat) => {
    for (let i = 0; i < 8; i++) {
      const data = dv.getBigUint64(at + 8 * i, true);
      const key = data ^ s64(sat + 8 * i);
      acc[i ^ 1] = add(acc[i ^ 1], data);
      acc[i] = add(acc[i], (key & 0xffffffffn) * (key >> 32n));
    }
  };
  const blockLen = 64 * 16;
  const blocks = Math.floor((len - 1) / blockLen);
  for (let n = 0; n < blocks; n++) {
    for (let s = 0; s < 16; s++) stripe(n * blockLen + 64 * s, 8 * s);
    for (let i = 0; i < 8; i++) acc[i] = mul(xorshift(acc[i], 47n) ^ s64(128 + 8 * i), P32_1);
  }
  const stripes = Math.floor((len - 1 - blockLen * blocks) / 64);
  for (let s = 0; s < stripes; s++) stripe(blocks * blockLen + 64 * s, 8 * s);
  stripe(len - 64, 192 - 64 - 7);
  const merge = (sat, start) => {
    let r = start;
    for (let i = 0; i < 4; i++) {
      r = add(r, fold(acc[2 * i] ^ s64(sat + 16 * i), acc[2 * i + 1] ^ s64(sat + 16 * i + 8)));
    }
    return avalanche(r);
  };
  return join128(merge(11, mul(BigInt(len), P64_1)), merge(117, ~mul(BigInt(len), P64_2) & M64));
}

// The xxh3-128 hash of `bytes`, as a bigint (`hd_base::hash128`).
export function xxh3_128(bytes) {
  const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  if (bytes.length <= 16) return short128(bytes, dv);
  if (bytes.length <= 240) return mid128(bytes, dv);
  return long128(bytes, dv);
}

// --- framing ---------------------------------------------------------------

const CRC_TABLE = Array.from({ length: 256 }, (_, i) => {
  let c = i;
  for (let bit = 0; bit < 8; bit++) c = c & 1 ? (c >>> 1) ^ 0xedb88320 : c >>> 1;
  return c >>> 0;
});

// CRC-32 (IEEE), the journal checksum.
export function crc32(bytes) {
  let c = 0xffffffff;
  for (const b of bytes) c = CRC_TABLE[(c ^ b) & 0xff] ^ (c >>> 8);
  return ~c >>> 0;
}

// A growable byte string that rows and payloads are written into.
class Bytes {
  constructor() {
    this.buf = new Uint8Array(256);
    this.len = 0;
  }
  room(n) {
    if (this.len + n <= this.buf.length) return;
    const next = new Uint8Array(Math.max(this.buf.length * 2, this.len + n));
    next.set(this.buf.subarray(0, this.len));
    this.buf = next;
  }
  byte(b) {
    this.room(1);
    this.buf[this.len++] = b;
  }
  raw(bytes) {
    this.room(bytes.length);
    this.buf.set(bytes, this.len);
    this.len += bytes.length;
  }
  uleb(v) {
    let x = BigInt(v);
    this.room(10);
    do {
      let b = Number(x & 0x7fn);
      x >>= 7n;
      if (x) b |= 0x80;
      this.buf[this.len++] = b;
    } while (x);
  }
  // A u64 or u128 as `bytes` little-endian bytes.
  le(v, bytes) {
    for (let i = 0; i < bytes; i++) this.byte(Number((BigInt(v) >> BigInt(8 * i)) & 0xffn));
  }
  view() {
    return this.buf.subarray(0, this.len);
  }
  clear() {
    this.len = 0;
  }
}

const ulebLen = (v) => {
  let n = 1;
  for (let x = BigInt(v) >> 7n; x; x >>= 7n) n++;
  return n;
};

// Row kinds, as journal.rs numbers them.
export const KIND = {
  header: 0,
  input: 1,
  call: 2,
  finish: 3,
  wake: 4,
  block: 5,
  abort: 6,
  cancel: 7,
  end: 8,
};
const KIND_NAMES = Object.keys(KIND);

// The format number of a `Header` row.
export const FORMAT = 1;
// A REPL session's journal cap: past it, recording stops.
export const SESSION_CAP = 64 << 20;

function appendRow(out, kind, index, payload) {
  const start = out.len;
  out.byte(kind);
  out.uleb(index);
  out.uleb(payload.length);
  out.raw(payload);
  out.le(crc32(out.buf.subarray(start, out.len)), 4);
}

// A reader over a payload; every read answers `undefined` past its end.
class Reader {
  constructor(b) {
    this.b = b;
    this.at = 0;
  }
  uleb() {
    let v = 0n;
    for (let shift = 0n; shift < 64n; shift += 7n) {
      const byte = this.b[this.at];
      if (byte === undefined) return undefined;
      this.at++;
      v |= BigInt(byte & 0x7f) << shift;
      if (!(byte & 0x80)) return v;
    }
    return undefined;
  }
  num() {
    const v = this.uleb();
    return v === undefined || v > 0xffffffffn ? undefined : Number(v);
  }
  bytes(n) {
    if (n === undefined || this.at + n > this.b.length) return undefined;
    const out = this.b.slice(this.at, this.at + n);
    this.at += n;
    return out;
  }
  le(n) {
    const b = this.bytes(n);
    if (b === undefined) return undefined;
    let v = 0n;
    for (let i = n - 1; i >= 0; i--) v = (v << 8n) | BigInt(b[i]);
    return v;
  }
  text() {
    const b = this.bytes(this.num());
    if (b === undefined) return undefined;
    try {
      return new TextDecoder("utf-8", { fatal: true }).decode(b);
    } catch {
      return undefined;
    }
  }
  handles() {
    const n = this.num();
    if (n === undefined) return undefined;
    const out = [];
    for (let i = 0; i < n; i++) {
      const h = this.num();
      if (h === undefined) return undefined;
      out.push(h);
    }
    return out;
  }
}

// Reads rows until the end or the first torn or corrupt row: the rows,
// `{ kind, index, payload }`, and the length of the valid prefix.
export function readRows(b) {
  const rows = [];
  let at = 0;
  for (;;) {
    const start = at;
    if (at >= b.length) return { rows, valid: start };
    const r = new Reader(b);
    r.at = at + 1;
    const kind = b[at];
    const index = r.uleb();
    const len = r.num();
    const payload = r.bytes(len);
    const crc = r.le(4);
    if (
      kind >= KIND_NAMES.length ||
      payload === undefined ||
      crc === undefined ||
      Number(crc) !== crc32(b.subarray(start, r.at - 4)) ||
      index !== BigInt(rows.length)
    ) {
      return { rows, valid: start };
    }
    rows.push({ kind, index: Number(index), payload });
    at = r.at;
  }
}

// The digest of a request's argument bytes (`journal::request_digest`).
export function requestDigest(args) {
  const tagged = new Uint8Array(7 + args.length);
  tagged.set([3, 0, 0, 0, 0x72, 0x65, 0x71]);
  tagged.set(args, 7);
  return xxh3_128(tagged) & M64;
}

// The request a `Call` row holds for the arguments `args`.
export const requestOf = (args) =>
  args.length <= 8
    ? { args: Uint8Array.from(args) }
    : { len: args.length, digest: requestDigest(args) };

const sameRequest = (a, b) =>
  a.args && b.args
    ? a.args.length === b.args.length && a.args.every((x, i) => x === b.args[i])
    : !a.args && !b.args && a.len === b.len && a.digest === b.digest;

// Appends an integer parameter to a call's arguments.
export function putIntArg(out, v) {
  out.uleb(BigInt.asUintN(64, BigInt(v)));
}

// A host call's arguments as a journal holds them: each scalar parameter
// in `values` by its type in `types` (integers as `putIntArg`, floats as
// their IEEE 754 bits, an `f32` widened to 8 bytes), then `tail`, the
// exchange buffer bytes the call reads, when not null.
export function callArgs(values, types, tail) {
  const out = new Bytes();
  const dv = new DataView(new ArrayBuffer(8));
  values.forEach((v, i) => {
    const type = types[i];
    if (type === "i32" || type === "i64") putIntArg(out, v);
    else if (type === "f64") {
      dv.setFloat64(0, Number(v), true);
      out.raw(new Uint8Array(dv.buffer));
    } else if (type === "f32") {
      dv.setFloat32(0, Number(v), true);
      out.le(BigInt(dv.getUint32(0, true)), 8);
    }
  });
  if (tail) out.raw(tail);
  return out.view().slice();
}

function putReply(out, value, result) {
  out.byte(value.tag | (result ? 4 : 0));
  if (value.tag === 1) out.uleb(BigInt.asUintN(64, BigInt(value.v)));
  else if (value.tag === 2) out.le(value.v, 8);
  else if (value.tag === 3) {
    out.uleb(value.v >>> 0);
    out.uleb(value.w >>> 0);
  }
  if (result) {
    out.uleb(result.length);
    out.raw(result);
  }
}

function getReply(r) {
  const tag = r.bytes(1)?.[0];
  if (tag === undefined) return undefined;
  const low = (v) => (v === undefined ? undefined : Number(BigInt.asIntN(32, v)));
  let value;
  switch (tag & 3) {
    case 0:
      value = { tag: 0 };
      break;
    case 1: {
      const v = r.uleb();
      if (v === undefined) return undefined;
      value = { tag: 1, v: BigInt.asIntN(64, v) };
      break;
    }
    case 2: {
      const v = r.le(8);
      if (v === undefined) return undefined;
      value = { tag: 2, v };
      break;
    }
    default: {
      const v = low(r.uleb());
      const w = low(r.uleb());
      if (v === undefined || w === undefined) return undefined;
      value = { tag: 3, v, w };
    }
  }
  let result = null;
  if (tag >> 2 === 1) {
    result = r.bytes(r.num());
    if (result === undefined) return undefined;
  } else if (tag >> 2 !== 0) return undefined;
  return { value, result };
}

const END_KINDS = ["exit", "trapped", "stopped", "cancelled", "failed"];

function decodeRow(row, methods) {
  const r = new Reader(row.payload);
  let event;
  switch (row.kind) {
    case KIND.header:
      event = { kind: "header", format: r.uleb(), execution: r.bytes(16) };
      break;
    case KIND.input:
      event = { kind: "input", number: r.num(), source: r.le(16), module: r.le(16) };
      break;
    case KIND.call: {
      const method = r.num();
      if (method === methods.length) methods.push([r.text(), r.text()]);
      const named = methods[method];
      if (!named || named.includes(undefined)) return undefined;
      const len = r.uleb();
      if (len === undefined) return undefined;
      const request =
        len <= 8n ? { args: r.bytes(Number(len)) } : { len: Number(len), digest: r.le(8) };
      const reply = getReply(r);
      if (!reply || (request.args ?? request.digest) === undefined) return undefined;
      event = { kind: "call", module: named[0], name: named[1], request, ...reply };
      break;
    }
    case KIND.finish: {
      const handle = r.num();
      const reply = getReply(r);
      if (!reply) return undefined;
      event = { kind: "finish", handle, ...reply };
      break;
    }
    case KIND.wake:
      event = { kind: "wake", poll: r.uleb(), handles: r.handles() };
      break;
    case KIND.block:
      event = { kind: "block", handles: r.handles() };
      break;
    case KIND.abort:
      event = { kind: "abort", handle: r.num() };
      break;
    case KIND.cancel:
      event = { kind: "cancel", poll: r.uleb() };
      break;
    default: {
      const tag = r.bytes(1)?.[0];
      if (tag === undefined || tag >= END_KINDS.length) return undefined;
      const end = { kind: END_KINDS[tag] };
      if (tag === 0) {
        end.status = r.bytes(1)?.[0];
        if (end.status === undefined) return undefined;
      }
      event = { kind: "end", end };
    }
  }
  if (Object.values(event).includes(undefined) || r.at !== row.payload.length) return undefined;
  return event;
}

// Decodes the rows of one journal, in order, or throws naming the first
// row whose payload does not decode.
export function decodeRows(rows) {
  const methods = [];
  return rows.map((row) => {
    const event = decodeRow(row, methods);
    if (!event) {
      const kind = KIND_NAMES[row.kind];
      throw new Error(
        `row ${row.index} (${kind[0].toUpperCase()}${kind.slice(1)}) does not decode`,
      );
    }
    return event;
  });
}

// --- the recorder ------------------------------------------------------------

// Writes one execution's journal in memory, as `journal::Recorder` does:
// the host's import call sites call `call`, `finish`, `block` or `abort`
// per host call; the driver `poll`, `wake` and `cancel`; a session `input`
// and `end` around each input. Past its cap, recording stops for good and
// the journal is dropped; `takeNotice` then answers true once.
export class Recorder {
  // `execution` is the 16 bytes of the execution id.
  constructor(cap, execution) {
    this.bytes = new Bytes();
    this.capBytes = cap;
    this.next = 0;
    this.methods = new Map();
    this.row = new Bytes();
    this.polls = 0;
    this.state = "on";
    this.row.uleb(FORMAT);
    this.row.raw(execution);
    this.push(KIND.header);
  }
  // The journal so far, or `null` once recording stopped at the cap.
  journal() {
    return this.state === "on" ? this.bytes.view() : null;
  }
  get cap() {
    return this.capBytes;
  }
  setCap(cap) {
    this.capBytes = cap;
  }
  takeNotice() {
    if (this.state !== "off") return false;
    this.state = "told";
    return true;
  }
  // A host call of the import `module` `name` with the arguments
  // `request` that returned `value` and, when not null, `result` bytes.
  call(module, name, request, value, result) {
    if (this.state !== "on") return;
    const key = `${module}\0${name}`;
    const known = this.methods.get(key);
    if (known === undefined) {
      this.row.uleb(this.methods.size);
      for (const text of [module, name]) {
        const b = utf8.encode(text);
        this.row.uleb(b.length);
        this.row.raw(b);
      }
      this.methods.set(key, this.methods.size);
    } else {
      this.row.uleb(known);
    }
    this.row.uleb(request.length);
    if (request.length <= 8) this.row.raw(request);
    else this.row.le(requestDigest(request), 8);
    putReply(this.row, value, result);
    this.push(KIND.call);
  }
  finish(handle, value, result) {
    if (this.state !== "on") return;
    this.row.uleb(handle);
    putReply(this.row, value, result);
    this.push(KIND.finish);
  }
  block(handles) {
    if (this.state !== "on") return;
    this.handles(handles);
    this.push(KIND.block);
  }
  abort(handle) {
    if (this.state !== "on") return;
    this.row.uleb(handle);
    this.push(KIND.abort);
  }
  poll() {
    this.polls += 1;
  }
  wake(handles) {
    if (this.state !== "on") return;
    this.row.uleb(this.polls);
    this.handles(handles);
    this.push(KIND.wake);
  }
  cancel() {
    if (this.state !== "on") return;
    this.row.uleb(this.polls);
    this.push(KIND.cancel);
  }
  // A REPL input numbered `number` starts, with its source text (a
  // string) and module bytes.
  input(number, source, module) {
    this.polls = 0;
    if (this.state !== "on") return;
    this.row.uleb(number);
    this.row.le(xxh3_128(utf8.encode(source)), 16);
    this.row.le(xxh3_128(module), 16);
    this.push(KIND.input);
  }
  end(end) {
    if (this.state !== "on") return;
    this.row.byte(END_KINDS.indexOf(end.kind));
    if (end.kind === "exit") this.row.byte(end.status);
    this.push(KIND.end);
  }
  handles(handles) {
    this.row.uleb(handles.length);
    for (const h of handles) this.row.uleb(h);
  }
  push(kind) {
    const len = this.row.len;
    const size = 1 + ulebLen(this.next) + ulebLen(len) + len + 4;
    if (this.bytes.len + size > this.capBytes) {
      this.state = "off";
      this.bytes = new Bytes();
      this.methods = new Map();
      this.row = new Bytes();
      return;
    }
    appendRow(this.bytes, kind, this.next, this.row.view());
    this.next += 1;
    this.row.clear();
  }
}

// --- replay ------------------------------------------------------------------

// A row, as a divergence message names what the record has.
function describe(event) {
  switch (event?.kind) {
    case undefined:
      return "nothing more";
    case "header":
      return "a header";
    case "input":
      return `input ${event.number}`;
    case "call":
      return `a call of ${event.module} ${event.name}`;
    case "finish":
      return `the finish of operation ${event.handle}`;
    case "wake":
      return `a wake after ${event.poll} polls`;
    case "block":
      return "a block";
    case "abort":
      return `the abort of operation ${event.handle}`;
    case "cancel":
      return "a cancel";
    default:
      return `its end: it ${ended(event.end)}`;
  }
}

// How an input ended, as a sentence's verb phrase.
export function ended(end) {
  switch (end.kind) {
    case "exit":
      return end.status === 0 ? "ended" : `ended with status ${end.status}`;
    case "trapped":
      return "panicked";
    case "stopped":
      return "was stopped";
    case "cancelled":
      return "was cancelled";
    default:
      return "failed to run";
  }
}

const sameEnd = (a, b) => a.kind === b.kind && a.status === b.status;

// Reads a session's journal into its execution id (16 bytes) and its
// inputs, `{ number, source, module, events, end }` with `end` null when
// the journal ends inside it. A torn tail is cut.
export function recorded(bytes) {
  const events = decodeRows(readRows(bytes).rows);
  const header = events.shift();
  if (header?.kind !== "header") throw new Error("the journal has no header");
  if (header.format !== BigInt(FORMAT)) {
    throw new Error(`the journal has format ${header.format}, not ${FORMAT}`);
  }
  const inputs = [];
  for (const event of events) {
    if (event.kind === "input") {
      const { number, source, module } = event;
      inputs.push({ number, source, module, events: [], end: null });
      continue;
    }
    const input = inputs.at(-1);
    if (!input || input.end) throw new Error(`the journal has ${describe(event)} outside an input`);
    if (event.kind === "end") input.end = event.end;
    else input.events.push(event);
  }
  return { execution: header.execution, inputs };
}

// Whether `source` is the text a recorded input ran, by its hash.
export const ran = (input, source) => xxh3_128(utf8.encode(source)) === input.source;

// The divergence of a replayed input: the message, as `Replay` words it.
export class Diverged extends Error {}

// Serves one recorded input's host results while it runs again
// (`replay::Replay`): each method throws `Diverged` at the first request
// that is not the record's next row, and keeps its message.
export class Replay {
  constructor(input) {
    this.number = input.number;
    this.events = [...input.events];
    this.polls = 0;
    this.diverged = null;
  }
  // The reply `{ value, result }` the record holds for a call of `module`
  // `name` with the arguments `args`.
  call(module, name, args) {
    const asked = `called ${module} ${name}`;
    const front = this.events[0];
    if (front?.kind === "call" && front.module === module && front.name === name) {
      if (!sameRequest(front.request, requestOf(args))) {
        this.diverge(`input ${this.number} ${asked} with other arguments than before`);
      }
      return this.events.shift();
    }
    return this.unexpected(asked);
  }
  finish(handle) {
    const front = this.events[0];
    if (front?.kind === "finish" && front.handle === handle) return this.events.shift();
    return this.unexpected(`finished operation ${handle}`);
  }
  // The handles of a recorded block, or null when the record has nothing
  // more (the block finds nothing pending, as the first run's did).
  block() {
    const front = this.events[0];
    if (front === undefined) return null;
    if (front.kind === "block") return this.events.shift().handles;
    return this.unexpected("blocked");
  }
  abort(handle) {
    const front = this.events[0];
    if (front?.kind === "abort" && front.handle === handle) this.events.shift();
    else this.unexpected(`aborted operation ${handle}`);
  }
  poll() {
    this.polls += 1;
  }
  // Whether the record's next row is a wake: the input waits for one.
  wakeNext() {
    return this.events[0]?.kind === "wake";
  }
  // The handles the record wakes the input with after its polls so far.
  wake() {
    const front = this.events[0];
    if (front?.kind === "wake" && front.poll === BigInt(this.polls))
      return this.events.shift().handles;
    return this.unexpected(`waited on the host after ${this.polls} polls`);
  }
  // The input ended with `end`: a divergence unless the record ended it
  // so, `recordedEnd`, after every row was served.
  end(end, recordedEnd) {
    if (this.diverged !== null) throw new Diverged(this.diverged);
    if (this.events.length) this.unexpected(`${ended(end)} early`);
    if (recordedEnd === null) {
      this.diverge(`input ${this.number} ${ended(end)}, but the record of it is cut short`);
    }
    if (!sameEnd(end, recordedEnd)) {
      this.diverge(`input ${this.number} ${ended(end)}, but before it ${ended(recordedEnd)}`);
    }
  }
  unexpected(asked) {
    return this.diverge(
      `input ${this.number} ${asked}, but the record has ${describe(this.events[0])}`,
    );
  }
  diverge(message) {
    this.diverged ??= message;
    throw new Diverged(this.diverged);
  }
}

// --- import types --------------------------------------------------------------

// The parameter and result types of each function a module imports, by
// `module\0name`: "i32", "i64", "f32", "f64" or "ref". A recorder encodes
// parameters by them and a replay converts served values to them.
export function importTypes(bytes) {
  const b = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  const r = new Reader(b);
  r.at = 8;
  const types = [];
  const out = new Map();
  const NUM = { 0x7f: "i32", 0x7e: "i64", 0x7d: "f32", 0x7c: "f64", 0x7b: "v128" };
  const sleb = () => {
    let shift = 0;
    let byte;
    do {
      byte = b[r.at++];
      shift += 7;
    } while (byte & 0x80);
    return shift;
  };
  const valtype = () => {
    const t = b[r.at++];
    if (NUM[t]) return NUM[t];
    if (t === 0x63 || t === 0x64) sleb();
    return "ref";
  };
  const vec = (each) => Array.from({ length: r.num() }, each);
  // A memory's or table's limits: flags, the minimum, and the maximum
  // when flag bit 0 is set.
  const limits = () => {
    const flags = r.num();
    r.num();
    if (flags & 1) r.num();
  };
  const functionType = () => {
    if (b[r.at++] !== 0x60) throw new Error("a module type is not a function");
    types.push({ params: vec(valtype), results: vec(valtype) });
  };
  while (r.at < b.length) {
    const id = b[r.at++];
    const size = r.num();
    const end = r.at + size;
    if (id === 1) {
      vec(functionType);
    } else if (id === 2) {
      vec(() => {
        const module = r.text();
        const name = r.text();
        const kind = b[r.at++];
        if (kind === 0x00) out.set(`${module}\0${name}`, types[r.num()]);
        else if (kind === 0x02) limits();
        else if (kind === 0x01) {
          valtype();
          limits();
        } else if (kind === 0x03) {
          valtype();
          r.at++;
        } else {
          r.at++;
          r.num();
        }
      });
      return out;
    }
    r.at = end;
  }
  return out;
}

package-providers.mjs.source:
// Helpers used by signature-generated NAME.host.mjs modules. Providers are
// trusted JS selected from package manifests after the root grants access.
// Guest contract data is never interpreted as module code or import paths.
import { Dec, Enc, HostContract, decodeUtf8 } from "./wire.mjs";

const fail = (message) => {
  throw new HostContract(`package host: ${message}`);
};
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const equalBytes = (a, b) => a.length === b.length && a.every((v, i) => v === b[i]);
const own = (v, k) => {
  if (v === null || typeof v !== "object" || !Object.hasOwn(v, k)) fail(`missing field ${k}`);
  return v[k];
};
const object = (fields) => Object.fromEntries(fields);
const named = (i) => `${i.identity.package}@${i.identity.version}/${i.identity.trait_path}`;

// Typed Serde transport is internal. Provider methods receive JS values:
// bigint integers, number floats, and ordinary arrays/objects. Using a flat
// stream preserves numeric kind and avoids multiplying container depth.
function encodePrivate(value) {
  const tokens = [];
  const pending = [{ value }];
  const active = new Set();
  while (pending.length) {
    const job = pending.pop();
    if (job.leave) {
      active.delete(job.leave);
      continue;
    }
    const v = job.value;
    if (v === null) tokens.push(["n"]);
    else if (typeof v === "boolean") tokens.push(["b", v]);
    else if (typeof v === "string") tokens.push(["s", v]);
    else if (typeof v === "bigint") {
      if (v < -(1n << 63n) || v >= 1n << 64n) fail("private integer outside 64-bit range");
      tokens.push([v < 0n ? "i" : "u", String(v)]);
    } else if (typeof v === "number") {
      if (!Number.isFinite(v)) tokens.push(["n"]);
      else {
        const bits = new DataView(new ArrayBuffer(8));
        bits.setFloat64(0, v, true);
        tokens.push(["f", bits.getBigUint64(0, true).toString(16).padStart(16, "0")]);
      }
    } else if (typeof v === "object") {
      if (active.has(v)) fail("cyclic private value");
      active.add(v);
      pending.push({ leave: v });
      if (Array.isArray(v)) {
        tokens.push(["a", v.length]);
        for (let i = v.length - 1; i >= 0; --i) pending.push({ value: v[i] });
      } else {
        if (![Object.prototype, null].includes(Object.getPrototypeOf(v)))
          fail("private value must be a plain object");
        const entries = Object.entries(v);
        tokens.push(["o", entries.length]);
        for (let i = entries.length - 1; i >= 0; --i) {
          pending.push({ value: entries[i][1] }, { value: entries[i][0] });
        }
      }
    } else fail("unsupported private value");
  }
  return JSON.stringify(tokens);
}

function decodePrivate(text) {
  let tokens;
  try {
    tokens = JSON.parse(text);
  } catch {
    fail("invalid private value transport");
  }
  if (!Array.isArray(tokens)) fail("invalid private value transport");
  const values = [];
  for (let i = tokens.length - 1; i >= 0; --i) {
    const token = tokens[i];
    if (!Array.isArray(token)) fail("invalid private value token");
    const [tag, v] = token;
    if (token.length !== (tag === "n" ? 1 : 2)) fail("invalid private value token");
    if (tag === "n") values.push(null);
    else if (tag === "b" && typeof v === "boolean") values.push(v);
    else if (tag === "s" && typeof v === "string") values.push(v);
    else if (["i", "u", "f"].includes(tag)) {
      if (
        typeof v !== "string" ||
        !(tag === "f" ? /^[0-9a-f]{16}$/ : /^(?:0|-?[1-9][0-9]*)$/).test(v)
      )
        fail("invalid private numeric token");
      const n = BigInt(tag === "f" ? "0x" + v : v);
      if (tag === "i") {
        if (n < -(1n << 63n) || n >= 1n << 63n) fail("private signed integer out of range");
        values.push(n);
      } else {
        if (n < 0n || n >= 1n << 64n) fail("private unsigned integer out of range");
        if (tag === "u") values.push(n);
        else {
          const bits = new DataView(new ArrayBuffer(8));
          bits.setBigUint64(0, n, true);
          const number = bits.getFloat64(0, true);
          if (!Number.isFinite(number)) fail("invalid private float");
          values.push(number);
        }
      }
    } else if (tag === "a" || tag === "o") {
      if (!Number.isSafeInteger(v) || v < 0 || v > values.length / (tag === "o" ? 2 : 1))
        fail("invalid private container length");
      if (tag === "a") values.push(Array.from({ length: v }, () => values.pop()));
      else {
        const entries = [];
        const keys = new Set();
        for (let n = 0; n < v; ++n) {
          const key = values.pop();
          if (typeof key !== "string" || keys.has(key)) fail("invalid private object key");
          keys.add(key);
          entries.push([key, values.pop()]);
        }
        values.push(Object.fromEntries(entries));
      }
    } else fail("invalid private value token");
  }
  if (values.length !== 1) fail("invalid private value framing");
  return values[0];
}

// Decode the compiler's data section, with canonical lengths and bounded
// nesting. Never interpret guest data as module source or import paths.
export function readPackageContract(bytes) {
  if (!(bytes instanceof Uint8Array)) fail("contract is not bytes");
  let at = 0;
  const byte = () => {
    if (at >= bytes.length) fail("truncated contract");
    return bytes[at++];
  };
  const boolean = () => {
    const v = byte();
    if (v > 1) fail("invalid contract boolean");
    return v === 1;
  };
  const count = () => {
    let n = 0;
    for (let shift = 0; shift < 35; shift += 7) {
      const b = byte();
      if (shift === 28 && b > 15) fail("oversized contract length");
      n += (b & 127) * 2 ** shift;
      if (b < 128) {
        if ((shift && b === 0) || n > bytes.length - at) fail("invalid contract length");
        return n;
      }
    }
    fail("invalid contract length");
  };
  const string = () => {
    const n = count();
    const b = bytes.subarray(at, at + n);
    at += n;
    try {
      return new TextDecoder("utf-8", { fatal: true, ignoreBOM: true }).decode(b);
    } catch {
      fail("invalid contract UTF-8");
    }
  };
  const vector = (read) => Array.from({ length: count() }, read);
  const fields = (depth) => vector(() => [string(), value(depth + 1)]);
  const value = (depth = 0) => {
    if (depth > 32) fail("contract nesting exceeds the boundary limit");
    const tag = byte();
    if ([0, 1, 2, 4, 5, 6, 7, 14].includes(tag)) return [tag];
    if (tag === 3) {
      const bits = byte();
      const signed = boolean();
      if (![8, 16, 32, 64].includes(bits)) fail("invalid integer width");
      return [tag, bits, signed];
    }
    if (tag === 8 || tag === 9) return [tag, value(depth + 1)];
    if (tag === 10) return [tag, vector(() => value(depth + 1))];
    if (tag === 11) return [tag, fields(depth)];
    if (tag === 12) return [tag, vector(() => [string(), fields(depth)])];
    if (tag === 13) return [tag, value(depth + 1), value(depth + 1)];
    if (tag === 15) return [tag, string()];
    fail("unknown contract value tag");
  };
  if ([byte(), byte(), byte(), byte()].join(",") !== "1,0,0,0") fail("unsupported ABI version");
  const interfaces = vector(() => ({
    identity: { package: string(), version: string(), trait_path: string() },
    module: string(),
    selectors: vector(string),
    handle: boolean(),
    methods: vector(() => ({
      name: string(),
      member: string(),
      wait: boolean() ? "may" : "never",
      params: vector(() => value()),
      result: value(),
    })),
  }));
  if (at !== bytes.length) fail("trailing contract bytes");
  const identities = new Set(),
    modules = new Set(),
    selectors = new Set();
  const unique = (set, k) => {
    if (!k || set.has(k)) fail("empty or duplicate contract name");
    set.add(k);
  };
  const checkValue = (v) => {
    const [tag, a, b] = v;
    if (tag === 15 && !interfaces.some((i) => i.handle && i.module === a))
      fail("missing handle interface");
    if (tag === 8 || tag === 9) checkValue(a);
    if (tag === 10) a.forEach(checkValue);
    if (tag === 11) checkFields(a);
    if (tag === 12) {
      const names = new Set();
      for (const [name, fs] of a) {
        unique(names, name);
        checkFields(fs);
      }
    }
    if (tag === 13) {
      checkValue(a);
      checkValue(b);
    }
  };
  const checkFields = (fs) => {
    const names = new Set();
    for (const [name, v] of fs) {
      unique(names, name);
      checkValue(v);
    }
  };
  for (const i of interfaces) {
    if (
      !i.identity.package ||
      !i.identity.trait_path ||
      !i.module.startsWith("hd:pkg:") ||
      i.module.length === 7
    )
      fail("invalid nominal identity");
    unique(identities, JSON.stringify([i.identity, i.handle]));
    unique(modules, i.module);
    for (const selector of i.selectors) {
      const parts = selector.split(".");
      if (
        i.handle ||
        parts.length < 2 ||
        !["dep", "pkg"].includes(parts[0]) ||
        parts.some((p) => !p)
      )
        fail("invalid source selector");
      unique(selectors, selector);
    }
    const methods = new Set(),
      imports = new Set(i.handle ? ["$release"] : []);
    for (const m of i.methods) {
      unique(methods, m.name);
      if (!m.member) fail("empty method member");
      for (const name of m.wait === "may" ? [`${m.name}.start`, `${m.name}.finish`] : [m.name])
        unique(imports, name);
      m.params.forEach(checkValue);
      checkValue(m.result);
    }
  }
  return interfaces;
}

// Each codec carries its canonical shape, checked against the data section
// before an instance starts. Encoding validates before the wire writer can
// coerce values (notably a negative unsigned LEB value).
export function createPackageRuntime(io, { module, grants = {} } = {}) {
  const handles = new Map();
  const handleMethods = new Map();
  let nextHandle = 1;
  const lifetime = new AbortController();
  const codec = (shape, enc, dec) => ({ shape, enc, dec });
  const unit = codec(
    [0],
    (_e, v) => {
      if (v !== undefined) fail("void result has a value");
    },
    () => undefined,
  );
  const bool = codec(
    [1],
    (e, v) => {
      if (typeof v !== "boolean") fail("expected bool");
      e.leb(v ? 1 : 0);
    },
    (d) => d.tag(2) === 1,
  );
  const int = (bits, signed) => {
    const low = signed ? -(1n << BigInt(bits - 1)) : 0n;
    const high = (1n << BigInt(bits - (signed ? 1 : 0))) - 1n;
    const check = (v) => {
      if (typeof v !== "bigint" && !(typeof v === "number" && Number.isSafeInteger(v)))
        fail("expected integer");
      const n = BigInt(v);
      if (n < low || n > high) fail("integer is out of range");
      return n;
    };
    return codec(
      [3, bits, signed],
      (e, v) => {
        const n = check(v);
        signed ? e.zz(n) : e.leb(n);
      },
      (d) => {
        const n = check(signed ? d.zz() : d.leb());
        return bits === 64 ? n : Number(n);
      },
    );
  };
  const char = codec(
    [2],
    (e, v) => {
      if (typeof v !== "string" || [...v].length !== 1) fail("expected char");
      const n = v.codePointAt(0);
      if (n >= 0xd800 && n <= 0xdfff) fail("invalid char");
      e.leb(n);
    },
    (d) => {
      const n = d.num();
      if (n > 0x10ffff || (n >= 0xd800 && n <= 0xdfff)) fail("invalid char");
      return String.fromCodePoint(n);
    },
  );
  const float = (tag, narrow) =>
    codec(
      [tag],
      (e, v) => {
        if (typeof v !== "number") fail("expected float");
        const n = narrow ? 4 : 8;
        e.room(n);
        const view = new DataView(e.buf.buffer, e.buf.byteOffset + e.len, n);
        if (narrow) view.setFloat32(0, v, true);
        else view.setFloat64(0, v, true);
        e.len += n;
      },
      (d) => {
        const n = narrow ? 4 : 8;
        if (d.at + n > d.b.length) fail("truncated float");
        const view = new DataView(d.b.buffer, d.b.byteOffset + d.at, n);
        const v = narrow ? view.getFloat32(0, true) : view.getFloat64(0, true);
        d.at += n;
        return v;
      },
    );
  const str = codec(
    [6],
    (e, v) => {
      if (typeof v !== "string") fail("expected string");
      e.str(v);
    },
    (d) => d.str(),
  );
  const bytes = codec(
    [7],
    (e, v) => {
      if (!(v instanceof Uint8Array)) fail("expected Uint8Array");
      e.bytes(v);
    },
    (d) => d.bytes().slice(),
  );
  const json = codec(
    [14],
    (e, v) => e.str(encodePrivate(v)),
    (d) => decodePrivate(d.str()),
  );
  const array = (xs, n = null) => {
    if (!Array.isArray(xs) || (n !== null && xs.length !== n)) fail("invalid array");
  };
  const list = (t) =>
    codec(
      [8, t.shape],
      (e, xs, tx) => {
        array(xs);
        e.leb(xs.length);
        for (const x of xs) t.enc(e, x, tx);
      },
      (d) => {
        const n = d.num();
        if (!Number.isSafeInteger(n) || n > 0xffffffff) fail("invalid list length");
        return Array.from({ length: n }, () => t.dec(d));
      },
    );
  const option = (t) =>
    codec(
      [9, t.shape],
      (e, v, tx) => {
        if (v === null) e.leb(0);
        else t.enc(e.leb(1), v, tx);
      },
      (d) => (d.tag(2) ? t.dec(d) : null),
    );
  const tuple = (ts) =>
    codec(
      [10, ts.map((t) => t.shape)],
      (e, xs, tx) => {
        array(xs, ts.length);
        ts.forEach((t, n) => t.enc(e, xs[n], tx));
      },
      (d) => ts.map((t) => t.dec(d)),
    );
  const fieldShape = (fs) => fs.map(([n, t]) => [n, t.shape]);
  const encFields = (e, v, fs, tx) => {
    for (const [n, t] of fs) t.enc(e, own(v, n), tx);
  };
  const decFields = (d, fs) => object(fs.map(([n, t]) => [n, t.dec(d)]));
  const record = (fs) =>
    codec(
      [11, fieldShape(fs)],
      (e, v, tx) => encFields(e, v, fs, tx),
      (d) => decFields(d, fs),
    );
  const enumeration = (vs) =>
    codec(
      [12, vs.map(([n, fs]) => [n, fieldShape(fs)])],
      (e, v, tx) => {
        const tag = own(v, "tag"),
          index = vs.findIndex(([n]) => n === tag);
        if (index < 0) fail("unknown enum variant");
        e.leb(index);
        encFields(e, own(v, "fields"), vs[index][1], tx);
      },
      (d) => {
        const [tag, fs] = vs[d.tag(vs.length)];
        return { tag, fields: decFields(d, fs) };
      },
    );
  const result = (ok, err) =>
    codec(
      [13, ok.shape, err.shape],
      (e, v, tx) => {
        const tag = own(v, "ok");
        if (typeof tag !== "boolean") fail("invalid Result tag");
        (tag ? ok : err).enc(e.leb(tag ? 0 : 1), own(v, tag ? "value" : "error"), tx);
      },
      (d) => (d.tag(2) ? { ok: false, error: err.dec(d) } : { ok: true, value: ok.dec(d) }),
    );
  const handle = (namespace) =>
    codec(
      [15, namespace],
      (e, v, tx) => {
        if ((typeof v !== "object" && typeof v !== "function") || v === null)
          fail("expected provider handle object");
        const methods = handleMethods.get(namespace);
        if (!methods || methods.some((name) => typeof v[name] !== "function"))
          fail("returned handle is missing a declared method");
        if (nextHandle > 0x7fffffff) fail("handle space exhausted");
        const id = nextHandle++;
        handles.set(id, { namespace, value: v });
        tx.push(id);
        e.leb(id);
      },
      () => fail("a handle cannot be passed as a data argument"),
    );
  const runtime = {
    unit,
    bool,
    char,
    int,
    f32: float(4, true),
    f64: float(5, false),
    str,
    bytes,
    json,
    list,
    option,
    tuple,
    record,
    enumeration,
    result,
    handle,
  };
  const bind = (contract, generated, providers) => {
    const required = readPackageContract(contract);
    const sections = module && WebAssembly.Module.customSections(module, "hd.capabilities");
    if (!sections || sections.length !== 1 || !equalBytes(contract, new Uint8Array(sections[0])))
      fail("generated glue does not match the guest contract");
    const shapes = generated.map((i) => ({
      ...i,
      methods: i.methods.map((m) => ({
        ...m,
        params: m.params.map((p) => p.shape),
        result: m.result.shape,
      })),
    }));
    if (
      !same(
        shapes,
        required.map(({ module, handle, methods }) => ({ module, handle, methods })),
      )
    )
      fail("generated method shapes do not match the contract");
    for (const i of generated.filter((i) => i.handle))
      handleMethods.set(
        i.module,
        i.methods.map((m) => m.member),
      );
    if (!Array.isArray(providers)) fail("providers must be explicit registrations");
    const registrations = new Map();
    for (const provider of providers) {
      const expected = readPackageContract(provider.contract);
      const root = expected.find(
        (i) => !i.handle && i.module === provider.module && same(i.identity, provider.identity),
      );
      if (!root || registrations.has(provider.module))
        fail("invalid or duplicate provider registration");
      const implementation = provider.implementation;
      if (
        implementation === null ||
        typeof implementation !== "object" ||
        ![Object.prototype, null].includes(Object.getPrototypeOf(implementation))
      )
        fail(`provider for ${named(root)} must default-export a plain object of methods`);
      registrations.set(provider.module, { expected, root, implementation });
    }
    const checkExpected = (needed, expected, seen = new Set()) => {
      if (seen.has(needed.module)) return;
      seen.add(needed.module);
      const i = expected.find(
        (i) =>
          i.module === needed.module &&
          i.handle === needed.handle &&
          same(i.identity, needed.identity),
      );
      if (!i) fail(`provider identity/schema mismatch for ${named(needed)}`);
      for (const m of needed.methods) {
        if (!i.methods.some((other) => same(m, other)))
          fail(`provider method/schema mismatch for ${named(needed)}.${m.member}`);
      }
      const visit = (v) => {
        if (v[0] === 15)
          checkExpected(
            required.find((i) => i.handle && i.module === v[1]),
            expected,
            seen,
          );
        if (v[0] === 8 || v[0] === 9) visit(v[1]);
        if (v[0] === 10) v[1].forEach(visit);
        if (v[0] === 11) v[1].forEach(([, t]) => visit(t));
        if (v[0] === 12) v[1].forEach(([, fs]) => fs.forEach(([, t]) => visit(t)));
        if (v[0] === 13) {
          visit(v[1]);
          visit(v[2]);
        }
      };
      for (const m of needed.methods) {
        m.params.forEach(visit);
        visit(m.result);
      }
    };
    for (const i of required.filter((i) => !i.handle)) {
      const registration = registrations.get(i.module);
      if (!registration) fail(`missing provider for ${named(i)}; register it explicitly`);
      checkExpected(i, registration.expected);
      if (i.selectors.some((s) => Object.hasOwn(grants, s) && grants[s] === false))
        fail(`capability denied: ${named(i)}`);
      for (const m of i.methods)
        if (
          !Object.hasOwn(registration.implementation, m.member) ||
          typeof registration.implementation[m.member] !== "function"
        )
          fail(`missing provider method ${named(i)}.${m.member}`);
    }
    const imports = Object.create(null);
    for (const i of generated) {
      const out = Object.create(null);
      if (i.handle)
        out.$release = (id) => {
          const h = handles.get(id);
          if (!h || h.namespace !== i.module) fail("release of an invalid handle");
          handles.delete(id);
        };
      for (const m of i.methods) {
        const key = `${i.module} ${m.name}`;
        const label = `${named(required.find((r) => r.module === i.module))}.${m.member}`;
        const write = (value) => {
          const tx = [];
          try {
            if (m.result === unit) {
              unit.enc(null, value);
              return m.wait === "may" ? 0 : undefined;
            }
            const e = new Enc();
            m.result.enc(e, value, tx);
            return io.put(e);
          } catch (error) {
            for (const id of tx) handles.delete(id);
            throw new HostContract(`${label}: ${error.message}`);
          }
        };
        const invoke = (raw, signal) => {
          if (lifetime.signal.aborted) fail("instance is closed");
          let receiver = registrations.get(i.module)?.implementation;
          if (i.handle) {
            const h = handles.get(raw.shift());
            if (!h || h.namespace !== i.module) fail("call of an invalid handle");
            receiver = h.value;
          }
          let args = [];
          if (m.params.length) {
            const len = raw.shift();
            if (!Number.isInteger(len) || len < 0) fail("invalid argument buffer length");
            const bytes = Uint8Array.from(io.view(len));
            if (!i.handle && m.params.length === 1 && m.params[0] === str)
              args = [decodeUtf8(bytes)];
            else {
              const d = new Dec(bytes);
              args = m.params.map((t) => t.dec(d));
              if (d.at !== bytes.length) fail("trailing argument bytes");
            }
          }
          if (raw.length) fail("wrong import arity");
          const f = receiver?.[m.member];
          if (typeof f !== "function") fail(`missing provider method ${m.member}`);
          try {
            const context = {
              signal,
              instanceSignal: lifetime.signal,
              pending(poll, done, abort = null, finish = null) {
                if (m.wait !== "may")
                  fail(`non-suspending method ${label} cannot create a pending operation`);
                if (typeof poll !== "function" || typeof done !== "function")
                  fail("a pending operation needs readiness and result functions");
                if (
                  (abort !== null && typeof abort !== "function") ||
                  (finish !== null && typeof finish !== "function")
                )
                  fail("pending cancellation and delivery hooks must be functions");
                if (!io.prepare) fail("the host cannot create pending operations");
                return io.prepare(poll, done, abort, finish);
              },
            };
            Object.defineProperty(context, "http", {
              enumerable: true,
              get() {
                if (!io.http) fail("the host does not provide HTTP policy services");
                return io.http;
              },
            });
            Object.defineProperty(context, "console", {
              enumerable: true,
              get() {
                if (!io.console) fail("the host does not provide Console policy services");
                return io.console;
              },
            });
            return f.call(receiver, ...args, context);
          } catch (error) {
            throw new HostContract(`${label}: provider threw ${String(error)}`);
          }
        };
        if (m.wait === "never")
          out[m.name] = (...raw) => {
            const value = invoke(raw, lifetime.signal);
            if (value && typeof value.then === "function") {
              Promise.resolve(value).catch(() => {});
              fail(`non-suspending method ${label} returned a Promise`);
            }
            const prepared = io.prepared?.(value);
            if (prepared) {
              try {
                prepared.abort?.();
              } finally {
                fail(`non-suspending method ${label} returned a pending operation`);
              }
            }
            return write(value);
          };
        else {
          out[`${m.name}.start`] = (...raw) => {
            const operation = new AbortController();
            const value = invoke(raw, operation.signal);
            const prepared = io.prepared?.(value);
            if (prepared) {
              const call = (hook) => {
                try {
                  return hook?.();
                } catch (error) {
                  throw new HostContract(`${label}: provider callback threw ${String(error)}`);
                }
              };
              return io.pending(
                prepared.at,
                () => call(prepared.done),
                key,
                () => {
                  const ready = call(prepared.poll);
                  if (typeof ready !== "boolean")
                    fail(`readiness probe for ${label} did not return a boolean`);
                  return ready;
                },
                () => {
                  operation.abort();
                  call(prepared.abort);
                },
                prepared.finish ? () => call(prepared.finish) : null,
              );
            }
            if (!value || typeof value.then !== "function") return [0, write(value)];
            let live = true,
              ready = false,
              rejected = false,
              kept,
              failure;
            Promise.resolve(value).then(
              (v) => {
                if (live) {
                  kept = v;
                  ready = true;
                }
              },
              (e) => {
                if (live) {
                  failure = e;
                  rejected = true;
                  ready = true;
                }
              },
            );
            return io.pending(
              performance.now(),
              () => {
                if (rejected) fail(`provider ${label} rejected: ${String(failure)}`);
                return kept;
              },
              key,
              () => ready,
              () => {
                live = false;
                kept = undefined;
                operation.abort();
              },
            );
          };
          out[`${m.name}.finish`] = (id) => write(io.finished(id, key));
        }
      }
      imports[i.module] = out;
    }
    return imports;
  };
  return Object.assign(runtime, {
    bind,
    close: () => {
      lifetime.abort();
      handles.clear();
    },
    handleCount: () => handles.size,
  });
}

